44	// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
45	// success; on failure prints an error tagged with `ctx` and returns "". The
46	// existence check is here, at the one resolver fast/cycle/cycle-gdb share, so a
47	// missing path fails with a clear "ELF not found" instead of being handed to the
48	// engine (e.g. qemu's cryptic "Unable to find the RISC-V BIOS"). Mirrors the
49	// up-front check run_hybrid already does.
50	std::string abs_elf(const std::string& path, const std::string& ctx) {
51	  std::error_code ec;
52	  fs::path abs = fs::absolute(path, ec);
53	  if (ec) {
54	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
55	                 ctx.c_str(), path.c_str());
56	    return "";
57	  }
58	  if (!fs::is_regular_file(abs, ec)) {
59	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
60	                 path.c_str());
61	    return "";
62	  }
63	  return abs.string();
64	}
