66	// Validate the lone-ELF positional shape the standalone models require: print
67	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
68	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
69	// spawns a --describe subprocess per Verilator build). `model` labels the error.
70	int check_one_elf(const Cli& cli, const char* model) {
71	  if (cli.positional.empty()) {
72	    std::fprintf(stderr,
73	                 "andesim run --mode %s: missing ELF (the workload to run; "
74	                 "e.g. a tests/fixtures/<name>.elf)\n",
75	                 model);
76	    return 2;
77	  }
78	  if (cli.positional.size() > 1) {
79	    std::fprintf(stderr,
80	                 "andesim run --mode %s: unexpected argument '%s' "
81	                 "(engine args go after --)\n",
82	                 model, cli.positional[1].c_str());
83	    return 2;
84	  }
85	  return 0;
86	}
87	
88	// Reject an ELF whose class width (rv32/rv64) does not match the engine it would
89	// run on -- a clear pre-flight error instead of a cryptic "not of ELFCLASSxx"
90	// from deep inside the engine. Both directions. Returns "" when they agree, when
91	// the ELF is unreadable/not-ELF (reported elsewhere), or when the engine
92	// declares no xlen (cannot judge). Shared by cycle and hybrid: one wording.
93	std::string elf_engine_arch_error(const std::string& elf,
94	                                  const EngineDescriptor& eng) {
95	  const int ex = elf_xlen(elf);
96	  if (ex == 0 || eng.xlen == 0 || ex == eng.xlen) return "";
97	  char buf[256];
98	  std::snprintf(buf, sizeof(buf),
99	                "ELF is rv%d but engine '%s' is rv%ld -- pick a matching engine "
100	                "or an rv%d ELF",
101	                ex, eng.id.c_str(), eng.xlen, ex);
102	  return buf;
103	}
104	
105	// Print the dry-run preview: the exact command(s) andesim WOULD spawn, each
106	// shell-quoted and labeled, executing nothing. Shared by every --mode so the
107	// preview format is identical; `labels[i]` annotates `argvs[i]` (e.g.
108	// "fast-leg [qemu64]", "standalone [qemu64]"). Always returns 0 -- a dry run
109	// reports the plan, it does not run it.
110	int print_dry_run(const std::vector<std::vector<std::string>>& argvs,
111	                  const std::vector<std::string>& labels) {
112	  std::printf("[andesim] dry-run: %zu command(s), not executed\n", argvs.size());
113	  for (size_t i = 0; i < argvs.size(); ++i) {
114	    std::printf("# command %zu/%zu: %s\n", i + 1, argvs.size(),
115	                labels[i].c_str());
116	    std::printf("%s\n", render_argv(argvs[i]).c_str());
117	  }
118	  return 0;
119	}
