121	// The standalone-passthrough spine shared by `fast` and `cycle`: both take a
122	// single ELF, then exec the resolved engine standalone with `extra` (model
123	// flags the framework forwards, e.g. fast's -m) followed by the post-`--`
124	// args verbatim (inherit stdio, no timeout, propagate exit code). The only
125	// per-model differences -- which engine, and how it is selected -- are resolved
126	// by the caller; `model` here only labels the positional diagnostics.
127	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
128	                   const char* model,
129	                   const std::vector<std::string>& extra = {}) {
130	  if (int rc = check_one_elf(cli, model)) return rc;
131	  // QEMU's -bios flag searches its data directory for relative paths rather
132	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
133	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
134	  if (elf.empty()) return 2;
135	  std::vector<std::string> args = extra;
136	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
137	  std::string err;
138	  // --dry-run: print the exact engine command and stop, spawning nothing. Built
139	  // from the same passthrough_argv run_passthrough would exec, so the preview is
140	  // faithful (the full qemu/vsim command, incl. -bios <elf> and any post-`--`).
141	  if (cli.dry_run) {
142	    const std::vector<std::string> argv =
143	        passthrough_argv(eng, "standalone", elf, args, err);
144	    if (!err.empty()) {
145	      std::fprintf(stderr, "andesim run: %s\n", err.c_str());
146	      return 2;
147	    }
148	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
149	  }
150	  int rc = run_passthrough(eng, "standalone", elf, args, err);
151	  if (!err.empty()) std::fprintf(stderr, "andesim run: %s\n", err.c_str());
152	  return rc;
153	}
