155	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
156	// only the built-in qemu descriptor, so it resolves that directly rather than
157	// discover_engines(), which would spawn a --describe subprocess per Verilator
158	// build only to discard them all here.
159	int run_fast(const Cli& cli) {
160	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
161	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
162	    std::fprintf(stderr,
163	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
164	                 "got '%s'\n",
165	                 cli.engine.c_str());
166	    return 2;
167	  }
168	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
169	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
170	  std::string err;
171	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
172	  if (!err.empty()) {
173	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
174	    return 2;
175	  }
176	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
177	  if (cli.gdb) {
178	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
179	    extra.push_back("-gdb");
180	    extra.push_back("tcp::" + port);
181	    extra.push_back("-S");
182	  }
183	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
184	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
185	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
186	  // ELF -- the override is the user's call.
187	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
188	  int xlen;
189	  if (cli.engine == kQemuId32) xlen = 32;
190	  else if (cli.engine == kQemuId64) xlen = 64;
191	  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
192	  // Only an explicit engine can disagree with the ELF (when none is given, xlen
193	  // == elf_w), so this guard already implies an explicit --engine.
194	  if (elf_w && elf_w != xlen)
195	    std::fprintf(stderr,
196	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
197	                 "(running as rv%d)\n",
198	                 cli.engine.c_str(), xlen, elf_w, xlen);
199	  return run_standalone(cli, builtin_qemu_arch(xlen), "fast", extra);
200	}
