202	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
203	// its --jtag-port only after it has reset and halted the hart, so the debugger we
204	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
205	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
206	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
207	// single debugger slot). Returns false on timeout.
208	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
209	  constexpr int kPollMs = 50;
210	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
211	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
212	      char line[512];
213	      while (std::fgets(line, sizeof line, f)) {
214	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
215	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
216	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
217	        unsigned lport = 0, st = 0;
218	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
219	            && st == 0x0A && lport == port) {
220	          std::fclose(f);
221	          return true;
222	        }
223	      }
224	      std::fclose(f);
225	    }
226	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
227	  }
228	  return false;
229	}
