231	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
232	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
233	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
234	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
235	  const char* iceman = std::getenv("ICEMAN");
236	  if (!iceman || !*iceman) {
237	    std::fprintf(stderr,
238	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
239	                 "(export ICEMAN=<path to ICEman binary>)\n");
240	    return 2;
241	  }
242	  // Build vsim argv from the standalone template, appending user passthrough
243	  // and the JTAG port flag.
244	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
245	  if (elf.empty()) return 2;
246	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
247	  std::vector<std::string> vsim_pass = cli.passthrough;
248	  vsim_pass.push_back("--jtag-port");
249	  vsim_pass.push_back(jtag_port);
250	  std::string err;
251	  const std::vector<std::string> vsim_argv =
252	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
253	  if (!err.empty()) {
254	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
255	    return 2;
256	  }
257	  std::fprintf(stderr,
258	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
259	               jtag_port.c_str());
260	  if (fork_background(vsim_argv) < 0) {
261	    std::fprintf(stderr,
262	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
263	    return 1;
264	  }
265	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
266	  // Wait for the port to be LISTENing before launching the debugger (it does not
267	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
268	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
269	  // but launch anyway if it never appears.
270	  if (const int pnum = std::atoi(jtag_port.c_str());
271	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
272	    std::fprintf(stderr,
273	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
274	                 "after 20s; launching the debugger anyway\n",
275	                 jtag_port.c_str());
276	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
277	  // localhost, port 9104) instead of its default real-hardware adapter; without
278	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
279	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
280	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
281	}
