283	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
284	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
285	// engine's own output. Unlike fast, this must discover the Verilator build(s)
286	// to resolve the engine (explicit --engine, else the sole one).
287	int run_accurate(const Cli& cli) {
288	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
289	  // --describe subprocess per Verilator build only to fail on the argument.
290	  if (int rc = check_one_elf(cli, "cycle")) return rc;
291	  // --mem-size is validated but has nothing to size: the cycle engine always
292	  // models its full DRAM window. Say so instead of silently ignoring it.
293	  if (!cli.mem_size.empty()) {
294	    std::string se;
295	    if (parse_size(cli.mem_size, se); !se.empty()) {
296	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
297	                   se.c_str());
298	      return 2;
299	    }
300	    std::fprintf(stderr,
301	                 "[andesim] --mem-size: the cycle engine models its full "
302	                 "DRAM window; nothing to size\n");
303	  }
304	  Discovery disc = discover_engines();
305	  std::string err;
306	  const EngineDescriptor* eng =
307	      resolve_accurate_engine(disc.engines, cli.engine, err);
308	  if (!eng) {
309	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
310	    // Surface why an expected engine may be absent (failed --describe, etc.).
311	    for (const std::string& w : disc.warnings)
312	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
313	    return 2;
314	  }
315	  // The ELF must match the engine's width: an rv32 ELF on an rv64 engine (or
316	  // vice versa) cannot run. Catch it here with a clear message instead of the
317	  // engine's cryptic "not of ELFCLASSxx". check_one_elf above guaranteed a lone
318	  // positional.
319	  if (std::string e = elf_engine_arch_error(cli.positional[0], *eng); !e.empty()) {
320	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", e.c_str());
321	    return 2;
322	  }
323	  // --dry-run previews the standalone command and spawns nothing, so it takes
324	  // precedence over the interactive --gdb path (a dry run launches no debugger).
325	  if (cli.gdb && !cli.dry_run) return run_cycle_gdb(cli, *eng);
326	  return run_standalone(cli, *eng, "cycle");
327	}
