329	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
330	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
331	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
332	// driver's tests/e2e.sh delegation with a single window-cycle line.
333	int run_hybrid(const Cli& cli) {
334	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
335	  auto fail = [](const std::string& msg) {
336	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
337	    return 2;
338	  };
339	
340	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
341	
342	  // Resolve to an absolute, existing path: a clean error beats a downstream
343	  // spawn failure, and pc-trigger resolution reads the ELF's .symtab.
344	  std::error_code ec;
345	  const fs::path elf = fs::absolute(cli.positional[0], ec);
346	  if (ec || !fs::is_regular_file(elf, ec))
347	    return fail("ELF not found: " + cli.positional[0]);
348	  const std::string elf_path = elf.string();
349	
350	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
351	  // mistake fails fast without spawning a --describe per Verilator build.
352	  std::string err;
353	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
354	  if (!err.empty()) return fail(err);
355	
356	  // hybrid_trigger has already guaranteed trig.kind is marker|pc (the only
357	  // hybrid triggers; unknown returned an error above) -- exactly the entry
358	  // boundary --verify needs the oracle to arm on.
359	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
360	  if (!err.empty()) return fail(err);
361	
362	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
363	  if (!cli.mem_size.empty()) {
364	    std::string se;
365	    mem = parse_size(cli.mem_size, se);
366	    if (!se.empty()) return fail("--mem-size: " + se);
367	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
368	    // guest RAM here. The physical mmap reserves one V-scratch page above the
369	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
370	    // page. Failing now beats allocating a huge mmap file first and letting
371	    // QEMU die late.
372	    if (mem > max_program_mem_bytes())
373	      return fail("--mem-size " + cli.mem_size +
374	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
375	                  "reservation)");
376	  }
377	
378	  // L26/F3: refuse a run whose static image would extend into the reserved
379	  // V-transport scratch page. Scheme D parks the scratch in the TOP page of the
380	  // physical mmap; a PT_LOAD segment reaching there means the ELF was linked for
381	  // more RAM than --mem-size grants, and QEMU would load it straight onto the
382	  // scratch -> silent corruption. Derive the page's start from
383	  // physical_mmap_bytes (the same sizing the mmap uses) rather than a bare
384	  // `mem`, so the threshold tracks the reservation shape instead of relying on
385	  // the +page/-page adjustments cancelling. ram_base is the fixed andes_ae350
386	  // DRAM base (0; see L10). Skipped when the ELF cannot be read -- downstream
387	  // reports it.
388	  {
389	    std::string e;
390	    const uint64_t top = elf_load_top(elf_path, e);
391	    const uint64_t scratch_gpa =
392	        static_cast<uint64_t>(physical_mmap_bytes(mem)) - HYBRID_V_SCRATCH_BYTES;
393	    if (e.empty() && top > scratch_gpa) {
394	      char msg[256];
395	      std::snprintf(msg, sizeof(msg),
396	                    "ELF static image ends at 0x%llx, overlapping the reserved "
397	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
398	                    "; raise --mem-size or shrink the image",
399	                    static_cast<unsigned long long>(top),
400	                    static_cast<unsigned long long>(scratch_gpa));
401	      return fail(msg);
402	    }
403	  }
404	
405	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
406	  // or the sole cycle-accurate engine (reusing the F8 selector).
407	  Discovery disc = discover_engines();
408	  const EngineDescriptor* acc =
409	      resolve_accurate_engine(disc.engines, cli.engine, err);
410	  if (!acc) {
411	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
412	    for (const std::string& w : disc.warnings)
413	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
414	    return 2;
415	  }
416	
417	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
418	  // cannot share architectural state with the rv64 fast leg).
419	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
420	  // ...and the ELF must match that engine width too (same guard as cycle).
421	  if (std::string e = elf_engine_arch_error(elf_path, *acc); !e.empty())
422	    return fail(e);
423	
424	  Plan plan;
425	  plan.elf = elf_path;
426	  plan.mem_size = mem;
427	  Step qemu_step{kQemuId64, "fast-leg", trig};
428	  Step vsim_step{acc->id, "accurate-leg", trig};
429	  vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
430	  plan.steps = {qemu_step, vsim_step};
431	
432	  // Banner to stderr so the window-cycle result stands alone on stdout.
433	  // vlen is the synced value the fast leg inherits from the engine.
434	  std::fprintf(stderr,
435	               "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
436	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
437	               elf.stem().string().c_str());
438	
439	  PlanOptions opts;
440	  opts.dry_run = cli.dry_run;
441	  const PlanResult r = run_plan(plan, disc.engines, opts);
442	  if (!r.ok()) {
443	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
444	    return 1;
445	  }
446	  // --dry-run: print the exact per-leg commands run_plan assembled -- the QEMU
447	  // fast leg (incl. the staged -readconfig from the engine's --print-qemu-config)
448	  // then the vsim accurate leg -- and stop. Nothing was spawned.
449	  if (cli.dry_run) {
450	    std::vector<std::string> labels;
451	    labels.reserve(plan.steps.size());
452	    for (const Step& s : plan.steps)
453	      labels.push_back(s.role + " [" + s.engine_id + "]");
454	    return print_dry_run(r.argvs, labels);
455	  }
456	  // Relay each leg's stdout verbatim: the program's own prints (QEMU1 phase-1
457	  // output, then anything the ROI wrote on vsim) belong to the user.
458	  for (const PhaseResult& p : r.phases)
459	    if (!p.out.empty()) std::fwrite(p.out.data(), 1, p.out.size(), stdout);
460	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
461	  // vsim mcycle delta.
462	  {
463	    const unsigned long long q_mc = r.phases[0].mcycle;
464	    const unsigned long long v_mc = r.phases[1].mcycle;
465	    std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
466	                trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
467	  }
468	
469	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
470	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
471	  // halt pc, and diff the two drains in-process. The oracle plan gets its
472	  // own fresh mmap: reusing the main run's would boot the oracle on the
473	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
474	  // output was already relayed from the main run.
475	  if (cli.verify) {
476	    char pcbuf[32];
477	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
478	                  static_cast<unsigned long long>(r.phases[1].st.pc));
479	    Trigger vtrig;
480	    vtrig.kind = "verify-" + trig.kind;
481	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
482	    vtrig.params["drain_pc"] = pcbuf;
483	
484	    Plan vplan;
485	    vplan.elf = elf_path;
486	    vplan.mem_size = mem;
487	    vplan.steps = {Step{kQemuId64, "fast-leg", vtrig}};
488	
489	    std::fprintf(stderr,
490	                 "[andesim] verify: oracle leg (pure QEMU drains at the ROI "
491	                 "exit, pc=%s)\n",
492	                 pcbuf);
493	    const PlanResult vr = run_plan(vplan, disc.engines);
494	    if (!vr.ok()) {
495	      std::fprintf(stderr, "andesim run --verify: %s\n", vr.error.c_str());
496	      return 1;
497	    }
498	    // Pass the cycle engine's supported Andes-CSR list so verify skips CSRs the
499	    // engine does not implement (it never restored/re-read them; comparing
500	    // would false-diff). Mirrors the resume/drain gating in vsim.
501	    const DiffReport d =
502	        diff_states(vr.phases[0].st, r.phases[1].st, acc->andes_csrs);
503	    print_diff_report(d);
504	    if (!d.ok()) {
505	      std::fprintf(stderr,
506	                   "andesim run --verify: vsim drain diverges from the "
507	                   "QEMU oracle\n");
508	      return 1;
509	    }
510	    std::printf("[verify] PASS: vsim drain matches the QEMU oracle\n");
511	  }
512	
513	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
514	              elf.stem().string().c_str());
515	  return 0;
516	}
517	
518	}  // namespace
519	
520	int cmd_run(const Cli& cli) {
521	  if (cli.model.empty()) {
522	    std::fprintf(stderr,
523	                 "andesim run: --mode fast|cycle|hybrid is required "
524	                 "(pick the composition; see 'andesim run --help')\n");
525	    return 2;
526	  }
527	  if (!find_model(cli.model)) {
528	    std::fprintf(stderr,
529	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
530	                 cli.model.c_str());
531	    return 2;
532	  }
533	  if (!cli.gdb_port.empty() && !cli.gdb) {
534	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
535	    return 2;
536	  }
537	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
538	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
539	  if (cli.gdb && cli.model == "hybrid") {
540	    std::fprintf(stderr,
541	                 "andesim run: --gdb is not supported with --mode hybrid\n");
542	    return 2;
543	  }
544	  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
545	  // composition has a second engine to check.
546	  if (cli.verify && cli.model != "hybrid") {
547	    std::fprintf(stderr,
548	                 "andesim run: --verify requires --mode hybrid (the %s "
549	                 "model has nothing to cross-check)\n",
550	                 cli.model.c_str());
551	    return 2;
552	  }
553	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window; fast and
554	  // cycle run the whole program and would silently drop them, handing back a
555	  // whole-program figure for the window the user asked for. Reject instead.
556	  if (!cli.trigger.empty() && cli.model != "hybrid") {
557	    std::fprintf(stderr,
558	                 "andesim run: --trigger applies only to --mode hybrid "
559	                 "(the ROI delimiter); fast/cycle run the whole program\n");
560	    return 2;
561	  }
562	  if (!cli.pc_end.empty() && cli.model != "hybrid") {
563	    std::fprintf(stderr,
564	                 "andesim run: --pc-end applies only to --mode hybrid "
565	                 "--trigger pc\n");
566	    return 2;
567	  }
568	  if (!cli.pc_start.empty() && cli.model != "hybrid") {
569	    std::fprintf(stderr,
570	                 "andesim run: --pc-start applies only to --mode hybrid "
571	                 "--trigger pc\n");
572	    return 2;
573	  }
574	  if (cli.model == "fast") return run_fast(cli);
575	  if (cli.model == "cycle") return run_accurate(cli);
576	  return run_hybrid(cli);  // model validated above; only hybrid remains
577	}
578	
579	}  // namespace andes_sim
